#!/usr/bin/env python3
import argparse, json, math, re
from collections import Counter
from difflib import SequenceMatcher
from pathlib import Path

STOP = {'a','an','and','as','at','be','been','being','by','for','from','he','her','him','his','i','in','into','is','it','its','of','on','or','she','that','the','their','them','they','this','to','was','were','with','you','your'}

def toks(s):
    return re.findall(r"[\w']+", s.lower(), re.UNICODE)

def content(s):
    return [x for x in toks(s) if x not in STOP]

def jaccard(a, b):
    a, b = set(a), set(b)
    return len(a & b) / len(a | b) if a or b else 0.0

def shape(a, b):
    return SequenceMatcher(None, toks(a), toks(b), autojunk=False).ratio()

def main():
    p = argparse.ArgumentParser()
    p.add_argument('--project', default='.')
    p.add_argument('--output', default='.runner/disagreement_docket.json')
    a = p.parse_args()
    root = Path(a.project).resolve()
    corpus = root / 'corpus'
    sources = (corpus / 'source.txt').read_text(encoding='utf-8').splitlines()
    targets = (corpus / 'target.masked.txt').read_text(encoding='utf-8').splitlines()
    refs = (corpus / 'vref.txt').read_text(encoding='utf-8').splitlines()
    if not (len(sources) == len(targets) == len(refs)):
        raise SystemExit('unaligned corpus files')
    visible = [(i + 1, refs[i], sources[i], targets[i]) for i in range(len(sources)) if targets[i].strip()]
    df = Counter()
    for _, _, source, _ in visible:
        df.update(set(content(source)))
    n = max(1, len(visible))
    tasks = json.loads((root / 'tasks.json').read_text(encoding='utf-8'))
    result = []
    for task in tasks:
        query = task['source_text']
        query_terms = content(query)
        def score_a(row):
            return jaccard(query_terms, content(row[2]))
        def score_b(row):
            row_terms = set(content(row[2]))
            rare = sum(1.0 + math.log((n + 1) / (1 + df[x])) for x in set(query_terms) & row_terms)
            return shape(query, row[2]) * 0.55 + rare / max(1, len(set(query_terms))) * 0.45
        ranked_a = sorted(visible, key=lambda row: (-score_a(row), row[0]))[:5]
        excluded = {row[0] for row in ranked_a[:2]}
        ranked_b = [row for row in sorted(visible, key=lambda row: (-score_b(row), row[0])) if row[0] not in excluded][:5]
        def packet(rows, scorer):
            return [{'line': row[0], 'ref': row[1], 'source': row[2], 'target': row[3], 'score': round(scorer(row), 6), 'covered_query_terms': sorted(set(query_terms) & set(content(row[2])))} for row in rows]
        pa, pb = packet(ranked_a, score_a), packet(ranked_b, score_b)
        top_a = pa[0] if pa else None
        top_b = pb[0] if pb else None
        eligible = bool(top_a and top_b and top_a['line'] != top_b['line'] and top_a['covered_query_terms'] and top_b['covered_query_terms'])
        result.append({'task_id': task['task_id'], 'source_text': query, 'packet_a_method': 'content-jaccard', 'packet_a': pa, 'packet_b_method': 'sequence-shape-plus-rare-term', 'packet_b': pb, 'eligible_for_agent_review': eligible})
    destination = (root / a.output).resolve()
    runner = (root / '.runner').resolve()
    if runner not in destination.parents:
        raise SystemExit('output must be under .runner/')
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(json.dumps({'method': 'context-gated-dual-derivation', 'tasks': result}, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print(json.dumps({'tasks': len(result), 'eligible_for_agent_review': sum(row['eligible_for_agent_review'] for row in result), 'output': str(destination.relative_to(root))}))

if __name__ == '__main__':
    main()
